(()=>{
 function sync(){
  const nav=document.querySelector('#workspacePhaseBar .app-sidenav');if(!nav)return;
  const cn=nav.querySelector('.app-sidenav-brand-cn'),en=nav.querySelector('.app-sidenav-brand-en');
  if(cn&&cn.textContent!=='工作台')cn.textContent='工作台';
  if(en&&en.textContent!=='WORKSPACE')en.textContent='WORKSPACE';
  const foot=nav.querySelector('.app-sidenav-foot');
  if(foot&&!foot.querySelector('.local-nav-explore')){const label=document.createElement('div');label.className='local-nav-explore';label.textContent='探索';foot.prepend(label);}
 }
 const host=document.querySelector('#workspacePhaseBar');
 if(host)new MutationObserver(sync).observe(host,{childList:true,subtree:true});
 sync();
})();

